const dec = <deciderecommendation.result>;
const ai = <draftrationale.rationale>;

const text = typeof ai === "string" ? ai.trim() : "";
const stems = { approve: "approv", hold: "hold", reject: "reject" };
const stem = stems[String(dec.recommendation)] || String(dec.recommendation);
const longCode = /[A-Z0-9]{12,}/.test(text);
const digitRun = /\d{9,}/.test(text);
const mentionsRec = text.toLowerCase().indexOf(stem) !== -1;
const aiOk = text.length > 0 && !longCode && !digitRun && mentionsRec;

return {
  invoice_id: dec.invoice_id,
  recommendation: dec.recommendation,
  escalate: dec.escalate,
  escalation_level: dec.escalation_level,
  rationale: String(aiOk ? text : dec.facts_text).replace(/["\\\n\r]/g, " "),
  rationale_source: aiOk ? "llm_verified" : "deterministic_fallback",
  reasons_text: dec.reasons_text,
  payment_action: "none"
};

const dec = <assemblecase.result>;
const rawDecision = <humanintheloop1.decision>;
const rawComment = <humanintheloop1.comment>;
const rawName = <humanintheloop1.approver_name>;
const rawLevel = <humanintheloop1.approver_level>;
const rawCorrection = <humanintheloop1.corrected_value>;
const failMode = String(<readchatrequest.result.test_mode>).trim().toLowerCase() === "fail_write";
const auditId = "AUD-" + Date.now();

const str = s => String(s === null || s === undefined ? "" : s).replace(/["\\\n\r]/g, " ").trim();
const decision = str(rawDecision).toLowerCase();
const comment = str(rawComment).slice(0, 200);
const name = str(rawName).slice(0, 60);
const correction = str(rawCorrection).slice(0, 200);
const level = str(rawLevel).toLowerCase().replace(/\s+/g, "_") === "senior_finance" ? "senior_finance" : "finance_approver";
const recommendation = str(dec.recommendation).toLowerCase();
const bankMismatch = str(dec.reasons_text).indexOf("bank_mismatch") !== -1;
const needsSenior = dec.escalate === true;

const allowed = ["approve", "reject", "correct", "escalate"];
let status = "";
let accepted = true;
let note = "";
let override = false;

if (allowed.indexOf(decision) === -1) {
  accepted = false; note = "Decision must be approve, reject, correct or escalate";
} else if (name.length === 0) {
  accepted = false; note = "Approver name is missing";
} else if (decision === "approve") {
  override = recommendation !== "approve";
  if (bankMismatch) { accepted = false; note = "An invoice with a bank mismatch cannot be approved"; }
  else if ((needsSenior || override) && level !== "senior_finance") { accepted = false; note = "Senior finance level is required to approve this invoice"; }
  else if (override && comment.length === 0) { accepted = false; note = "A comment is required to approve against the recommendation"; }
  else { status = "Approved"; }
} else if (decision === "reject") {
  override = recommendation === "approve";
  status = "Rejected";
} else if (decision === "correct") {
  status = "Correction requested";
} else {
  status = "Escalated";
}
if (!accepted) status = "Hold - approval not accepted";

const details = "Decision " + (decision || "none") + " by " + (name || "unknown") + " (" + level + "). Recommendation " + recommendation
  + ". " + (accepted ? "Accepted" : "Not accepted: " + note) + ". Override " + (override ? "yes" : "no")
  + ". Comment: " + (comment || "none") + (correction ? ". Correction note: " + correction : "");

return {
  invoice_id: dec.invoice_id,
  status: status,
  recommendation: recommendation,
  accepted: accepted,
  override: override,
  decision: decision,
  updated_by: name || "unknown",
  approver_level: level,
  details_text: details,
  payment_action: "none",
  audit_id: auditId,
  audit_ref_write: failMode ? 'BROKEN"VALUE' : auditId,
  timestamp: new Date().toISOString()
};

const id = <readchatrequest.result.invoice_id>;
const why = <validatereferences.result.errors_text>;
return "I could not review " + id + ". Reason: " + why + ". Nothing was changed.";

const f = <finaldecision.result>;
const extra = f.accepted ? (f.override ? " This went against the recommendation and was logged as an override." : "") : " The approval was not accepted, so see the audit log for the reason.";
return "Decision recorded for " + f.invoice_id + ": " + f.status + " (" + f.updated_by + ")." + extra;

const id = <readchatrequest.result.invoice_id>;
const why = <validatefields.result.errors_text>;
return "I could not review " + id + ". Reason: " + why + ". Nothing was changed. Please correct the record and try again.";

const raw = <start.input>;
const msg = (raw === undefined || raw === null) ? "" : String(raw).replace(/["\\\n\r]/g, " ").trim();
const found = msg.match(/INV-\d{3}/i);
const invoiceId = found ? found[0].toUpperCase() : "";
const mode = String(<readchatrequest.result.test_mode>).trim().toLowerCase();
return { invoice_id: invoiceId, test_mode: mode === "" ? "off" : mode, message: msg.slice(0, 200) };

const rows = <getinvoice.rows>;
const blank = v => v === null || v === undefined || String(v).trim() === "";
const out = (errors, extra) => Object.assign({
  valid: errors.length === 0,
  errors: errors,
  errors_text: errors.join("; ").replace(/["\\\n\r]/g, " "),
  audit_id: "AUD-" + Date.now(),
  timestamp: new Date().toISOString()
}, extra || {});

if (rows.length !== 1) {
  return out([rows.length === 0 ? "Invoice not found" : "Invoice ID is not unique"]);
}

const inv = rows[0].data;
const errors = [];

const required = ["invoice_id","supplier_id","supplier_invoice_no","po_id","invoice_date",
  "currency","item_description","quantity","unit_price","subtotal","tax_rate",
  "tax_amount","total_amount","bank_account_on_invoice"];
const missing = required.filter(f => blank(inv[f]));
missing.forEach(f => errors.push("Missing required field: " + f));

[["invoice_id", /^INV-\d{3}$/], ["supplier_id", /^SUP-\d{3}$/],
 ["po_id", /^PO-\d{3}$/], ["currency", /^[A-Z]{3}$/]].forEach(pair => {
  const f = pair[0];
  if (!blank(inv[f]) && !pair[1].test(String(inv[f]))) errors.push("Invalid format: " + f);
});

["quantity","unit_price","subtotal","tax_rate","tax_amount","total_amount"].forEach(f => {
  if (!blank(inv[f]) && !(Number.isFinite(Number(inv[f])) && Number(inv[f]) >= 0)) {
    errors.push("Invalid number: " + f);
  }
});
if (!blank(inv.quantity) && !(Number(inv.quantity) > 0)) errors.push("Quantity must be greater than 0");

if (!blank(inv.invoice_date)) {
  const d = Date.parse(inv.invoice_date);
  if (isNaN(d)) errors.push("Invalid format: invoice_date");
  else if (d > Date.now()) errors.push("invoice_date is in the future");
}

if (String(inv.status).toLowerCase() !== "pending") {
  errors.push("Invoice already processed (status: " + inv.status + ")");
}

return out(errors, { invoice_id: inv.invoice_id, supplier_id: inv.supplier_id, po_id: inv.po_id, missing_fields: missing });

const inv = <getinvoice.rows>[0].data;
const sup = <getsupplier.rows>;
const po = <getpo.rows>;
const grn = <getgrns.rows>;
const errors = [];

if (sup.length !== 1) {
  errors.push("Supplier not found in Supplier Master");
} else if (String(sup[0].data.status).toLowerCase() !== "active") {
  errors.push("Supplier is not active");
}

if (po.length !== 1) {
  errors.push("Purchase order not found");
} else if (po[0].data.supplier_id !== inv.supplier_id) {
  errors.push("PO belongs to a different supplier");
}

if (po.length === 1 && grn.length === 0) {
  errors.push("No goods receipt found for the PO");
}

let grnQty = 0;
grn.forEach(g => { grnQty += Number(g.data.quantity_received); });

return {
  valid: errors.length === 0,
  errors: errors,
  errors_text: errors.join("; ").replace(/["\\\n\r]/g, " "),
  audit_id: "AUD-" + Date.now(),
  timestamp: new Date().toISOString(),
  supplier_name: sup.length === 1 ? sup[0].data.supplier_name : null,
  grn_count: grn.length,
  grn_total_qty: grnQty
};

const inv = <getinvoice.rows>[0].data;
const sup = <getsupplier.rows>[0].data;
const po = <getpo.rows>[0].data;
const grn = <getgrns.rows>;
const all = <getallinvoice.rows>;

const PRICE_TOL_PCT = 2;
const TOTAL_TOL_PCT = 2;
const MONEY_TOL = 0.01;
const HIGH_VALUE = 50000;
const JUMP_PCT = 20;

const num = v => Number(v);
const round2 = n => Math.round(n * 100) / 100;
const pct = (a, b) => b === 0 ? 0 : round2(((a - b) / b) * 100);
const str = s => String(s === null || s === undefined ? "" : s);
const norm = s => str(s).toUpperCase().replace(/[^A-Z0-9]/g, "");
const clean = s => str(s).replace(/\s+/g, "").toUpperCase();
const day = d => str(d).slice(0, 10);
const cents = n => Math.round(num(n) * 100);
const mask = s => { const c = clean(s); return c.length === 0 ? "none" : "****" + c.slice(-4); };
const safe = s => String(s).replace(/["\\\n\r]/g, " ");

const dup = (() => {
  const found = [];
  all.forEach(r => {
    const o = r.data;
    if (o.invoice_id === inv.invoice_id) return;
    if (str(o.invoice_id) > str(inv.invoice_id)) return;
    if (o.supplier_id === inv.supplier_id && norm(o.supplier_invoice_no) === norm(inv.supplier_invoice_no)) {
      found.push(o.invoice_id + " (same supplier and invoice number)");
    } else if (cents(o.total_amount) === cents(inv.total_amount) && day(o.invoice_date) === day(inv.invoice_date)) {
      found.push(o.invoice_id + " (same amount and date)");
    }
  });
  return { suspected: found.length > 0, text: found.join("; ") };
})();

const match = (() => {
  const issues = [];
  const add = (check, detail) => issues.push(check + ": " + detail);
  let received = 0;
  grn.forEach(g => { received += num(g.data.quantity_received); });
  const ordered = num(po.quantity_ordered);
  const qty = num(inv.quantity);
  let prior = 0;
  all.forEach(r => {
    const o = r.data;
    if (o.po_id === inv.po_id && o.invoice_id !== inv.invoice_id && str(o.status).toLowerCase() === "approved") prior += num(o.quantity);
  });
  if (str(inv.currency) !== str(po.currency)) add("currency", "Invoice currency " + inv.currency + " differs from PO currency " + po.currency);
  if (qty > received) add("quantity", "Invoiced quantity " + qty + " exceeds received quantity " + received);
  else if (prior > 0 && (prior + qty) > received) add("quantity", "Quantity already approved on this PO (" + prior + ") plus this invoice (" + qty + ") exceeds received quantity " + received);
  if (qty > ordered) add("quantity", "Invoiced quantity " + qty + " exceeds ordered quantity " + ordered);
  const priceVar = pct(num(inv.unit_price), num(po.unit_price));
  if (Math.abs(priceVar) > PRICE_TOL_PCT) add("unit_price", "Unit price " + inv.unit_price + " differs from PO price " + po.unit_price + " by " + priceVar + " percent, tolerance " + PRICE_TOL_PCT + " percent");
  if (Math.abs(num(inv.tax_rate) - num(po.tax_rate)) > 0.0001) add("tax", "Tax rate " + inv.tax_rate + " differs from PO tax rate " + po.tax_rate);
  const subCalc = round2(qty * num(inv.unit_price));
  if (Math.abs(subCalc - num(inv.subtotal)) > MONEY_TOL) add("arithmetic", "Subtotal " + inv.subtotal + " does not equal quantity x unit price " + subCalc);
  const taxCalc = round2(num(inv.subtotal) * num(inv.tax_rate));
  if (Math.abs(taxCalc - num(inv.tax_amount)) > MONEY_TOL) add("tax", "Tax amount " + inv.tax_amount + " does not equal subtotal x tax rate " + taxCalc);
  const totCalc = round2(num(inv.subtotal) + num(inv.tax_amount));
  if (Math.abs(totCalc - num(inv.total_amount)) > MONEY_TOL) add("arithmetic", "Total " + inv.total_amount + " does not equal subtotal + tax " + totCalc);
  const expectedTotal = round2(qty * num(po.unit_price) * (1 + num(po.tax_rate)));
  const totalVar = pct(num(inv.total_amount), expectedTotal);
  if (Math.abs(totalVar) > TOTAL_TOL_PCT) add("total", "Invoice total " + inv.total_amount + " differs from expected PO-based total " + expectedTotal + " by " + totalVar + " percent");
  return { ok: issues.length === 0, issues: issues, qty: qty, received: received, ordered: ordered, priceVar: priceVar, totalVar: totalVar };
})();

const fraud = (() => {
  const flags = [];
  const bankMismatch = clean(inv.bank_account_on_invoice) !== clean(sup.bank_account);
  if (bankMismatch) flags.push("bank_mismatch: Bank account on invoice (" + mask(inv.bank_account_on_invoice) + ") differs from Supplier Master (" + mask(sup.bank_account) + ")");
  const hist = all.filter(r => r.data.supplier_id === inv.supplier_id && r.data.item_description === inv.item_description && r.data.invoice_id !== inv.invoice_id && str(r.data.status).toLowerCase() === "approved");
  if (hist.length > 0) {
    let sum = 0;
    hist.forEach(r => { sum += num(r.data.unit_price); });
    const avg = round2(sum / hist.length);
    const jump = avg > 0 ? pct(num(inv.unit_price), avg) : 0;
    if (jump > JUMP_PCT) flags.push("price_jump: Unit price " + inv.unit_price + " is " + jump + " percent above the average approved price " + avg);
  }
  const highValue = num(inv.total_amount) > HIGH_VALUE;
  if (highValue) flags.push("high_value: Total " + inv.total_amount + " " + inv.currency + " exceeds the threshold of " + HIGH_VALUE);
  const patterns = [
    /ignore\s+(all\s+)?(previous|prior|above)/i,
    /system\s+(note|prompt|message|instruction)/i,
    /(mark|set)\s+(this\s+)?(invoice\s+)?(as\s+)?approved/i,
    /(update|change)\s+(the\s+)?(supplier\s+)?bank/i,
    /note\s+to\s+(the\s+)?(ai|assistant|model)/i
  ];
  const hit = ["notes", "item_description", "supplier_invoice_no"].filter(f => patterns.some(p => p.test(str(inv[f]))));
  if (hit.length > 0) flags.push("possible_prompt_injection: Instruction-like text found in " + hit.join(", ") + ". The text was ignored.");
  return { flags: flags, bankMismatch: bankMismatch, highValue: highValue, bankInv: mask(inv.bank_account_on_invoice), bankMaster: mask(sup.bank_account) };
})();

const reasons = [];
if (dup.suspected) reasons.push("Possible duplicate: " + dup.text);
match.issues.forEach(i => reasons.push("Discrepancy (" + i + ")"));
fraud.flags.forEach(f => reasons.push("Flag " + f));

const otherFlags = fraud.flags.filter(f => f.indexOf("high_value") !== 0);
let recommendation = "approve";
let basis = "All checks passed";
if (fraud.bankMismatch) {
  recommendation = "hold";
  basis = "Bank details differ from Supplier Master, which forces a hold";
} else if (dup.suspected) {
  recommendation = "reject";
  basis = "Suspected duplicate invoice";
} else if (!match.ok || otherFlags.length > 0) {
  recommendation = "hold";
  basis = "Discrepancies or risk flags need review";
} else if (fraud.highValue) {
  basis = "Checks passed, but high value requires senior approval";
}
const escalate = fraud.flags.length > 0;

const facts = "Invoice " + inv.invoice_id + " from " + inv.supplier_id + " for " + inv.total_amount + " " + inv.currency
  + ". Recommendation: " + recommendation + ". Basis: " + basis
  + ". Invoiced qty " + match.qty + ", received qty " + match.received + ", ordered qty " + match.ordered
  + ". Unit price variance " + match.priceVar + " percent. Total variance " + match.totalVar + " percent"
  + ". Supplier bank on invoice " + fraud.bankInv + " vs master " + fraud.bankMaster
  + ". Findings: " + (reasons.length > 0 ? reasons.join(" | ") : "none") + ".";

return {
  invoice_id: inv.invoice_id,
  recommendation: recommendation,
  basis: basis,
  escalate: escalate,
  escalation_level: escalate ? "senior_finance" : "finance_approver",
  approval_required: true,
  payment_action: "none",
  reasons_text: safe(reasons.join("; ")),
  facts_text: safe(facts),
  checks: { duplicate: dup.suspected, match_ok: match.ok, fraud_flags: fraud.flags.length },
  audit_id: "AUD-" + Date.now(),
  timestamp: new Date().toISOString()
};

const c = <assemblecase.result>;
const lines = [
  "Invoice " + c.invoice_id + ": recommendation " + String(c.recommendation).toUpperCase() + ".",
  c.rationale,
  "Escalation: " + (c.escalate ? String(c.escalation_level).replace("_", " ") + " approval required." : "standard finance approval."),
  "Findings: " + (c.reasons_text ? c.reasons_text : "none") + ".",
  "This is a recommendation only. A finance approver must decide. I never make payments or change bank details.",
  "Use the approval link to record your decision."
];
return lines.join("\n");
